import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/TEMPORARY.md","filePath":"manual-en/TEMPORARY.md","lastUpdated":1785684581000}'),r={name:"manual-en/TEMPORARY.md"};function n(s,t,c,i,p,m){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h3 id="_13-6-temporary" tabindex="-1">13.6 TEMPORARY <a class="header-anchor" href="#_13-6-temporary" aria-label="Permalink to &quot;13.6 TEMPORARY&quot;">​</a></h3><pre><code>TEMPORARY.
</code></pre><p><code>TEMPORARY</code> is used to make the effects of transformations following its execution temporary. These transformations affect only the execution of the next procedure or procedure-like command. Their effects are not be saved to the active dataset.</p><p>The only specification on <code>TEMPORARY</code> is the command name.</p><p><code>TEMPORARY</code> may not appear within a <code>DO IF</code> or <code>LOOP</code> construct. It may appear only once between procedures and procedure-like commands.</p><p>Scratch variables cannot be used following <code>TEMPORARY</code>.</p><h4 id="_13-6-1-example-temporary" tabindex="-1">13.6.1 Example Temporary <a class="header-anchor" href="#_13-6-1-example-temporary" aria-label="Permalink to &quot;13.6.1 Example Temporary&quot;">​</a></h4><p>In Example 13.4 there are two <code>COMPUTE</code> transformation. One of them immediatly follows a <code>TEMPORARY</code> command, and therefore has effect only for the next procedure, which in this case is the first <code>DESCRIPTIVES</code> command.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data list notable /x 1-2. begin data.  2  4 10 15 20 24 end data.  compute x=x/2.  temporary. compute x=x+3.  descriptives x. descriptives x.</span></span></code></pre></div><p><strong>Example 13.4:</strong> Running a <code>COMPUTE</code> transformation after <code>TEMPORARY</code></p><p>The data read by the first <code>DESCRIPTIVES</code> procedure are 4, 5, 8, 10.5, 13, 15. The data read by the second <code>DESCRIPTIVES</code> procedure are 1, 2, 5, 7.5, 10, 12. This is because the second <code>COMPUTE</code> transformation has no effect on the second <code>DESCRIPTIVES</code> procedure. You can check these figures in Result 13.2.</p><table tabindex="0"><thead><tr><th></th><th>N</th><th>Mean</th><th>Std Dev</th><th>Minimum</th><th>Maximum</th></tr></thead><tbody><tr><td>x</td><td>6</td><td>9.25</td><td>4.38</td><td>4</td><td>15</td></tr><tr><td>Valid N (listwise)</td><td>6</td><td></td><td></td><td></td><td></td></tr><tr><td>Missing N (listwise)</td><td>0</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>N</td><td>Mean</td><td>Std Dev</td><td>Minimum</td><td>Maximum</td></tr><tr><td>x</td><td>6</td><td>6.25</td><td>4.38</td><td>1</td><td>12</td></tr><tr><td>Valid N (listwise)</td><td>6</td><td></td><td></td><td></td><td></td></tr><tr><td>Missing N (listwise)</td><td>0</td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Result 13.2:</strong> The results of running two consecutive <code>DESCRIPTIVES</code> commands after a temporary transformation</p>`,13)])])}const u=e(r,[["render",n]]);export{h as __pageData,u as default};
